// Starts, watches and stops the parts of a company's factory, and keeps the
// light of each one. It only starts and stops programs: what the parts are
// comes from the products' kits and the extensions.
import { addressOf, linkOf, portOf } from "@software-factory/core";
import { failLight, newPartLight, resetLight, setLight, viewOf, } from "./part-light.js";
import { answers, portTaken } from "./probe.js";
import { foreignFolder, runsHere } from "./listener.js";
import { folderOf, partById, startPart, takenByAnotherCopy, } from "./start-part.js";
export class Launcher {
    root;
    parts;
    inner = new Map();
    listeners = new Set();
    timer;
    ticking = false;
    // root: the factory folder; settings files and relative folders resolve
    // from there (a part's folder may also be absolute).
    constructor(options) {
        this.root = options.root;
        this.parts = options.parts;
        for (const part of this.parts)
            this.inner.set(part.id, newPartLight(part));
        this.timer = setInterval(() => {
            void this.tick();
        }, options.everyMs ?? 3000);
    }
    // The factory changed (a product added): the new list of parts. Parts
    // already known keep their state, so what runs keeps running.
    setParts(parts) {
        this.parts = parts;
        for (const part of parts)
            if (!this.inner.has(part.id))
                this.inner.set(part.id, newPartLight(part));
        this.notify();
    }
    state() {
        return this.parts.map((part) => viewOf(part, this.get(part.id), linkOf(part, this.parts, this.root)));
    }
    subscribe(listener) {
        this.listeners.add(listener);
        return () => {
            this.listeners.delete(listener);
        };
    }
    // Starts every part that starts with everything ("auto").
    async startAll() {
        await Promise.all(this.parts.filter((p) => p.start === "auto").map((p) => this.start(p.id)));
    }
    // Starts a part, what it depends on first. Asked twice, it starts once.
    start(id) {
        const inner = this.get(id);
        inner.starting ??= startPart(this.starter(), this.part(id)).finally(() => {
            inner.starting = null;
            this.notify();
        });
        return inner.starting;
    }
    // Stops a part, what depends on it first.
    async stop(id) {
        const part = this.part(id);
        for (const dependent of this.dependentsOf(part))
            await this.stopProgram(dependent);
        await this.stopProgram(part);
        this.notify();
    }
    // Stops and starts it again, and what depended on it and was running.
    async restart(id) {
        const before = this.dependentsOf(this.part(id)).filter((p) => this.get(p.id).light === "running" && !this.get(p.id).outside);
        await this.stop(id);
        await this.start(id);
        for (const dependent of before)
            await this.start(dependent.id);
    }
    // Stops everything, in reverse order: what needs a part stops before it.
    async stopAll() {
        for (const part of [...this.parts].reverse())
            await this.stopProgram(part);
        this.notify();
    }
    // Stops everything at once, when the factory itself is closing.
    stopNow() {
        for (const inner of this.inner.values()) {
            inner.stopping = true;
            inner.program?.stopNow();
        }
    }
    close() {
        clearInterval(this.timer);
    }
    starter() {
        return {
            root: this.root,
            parts: this.parts,
            lightOf: (id) => this.get(id),
            start: (id) => this.start(id),
            set: (inner, light, step) => {
                this.set(inner, light, step);
            },
            fail: (inner, problem) => {
                this.fail(inner, problem);
            },
            reset: (inner) => {
                resetLight(inner);
            },
            programEnded: (part, program) => {
                this.programEnded(part, program);
            },
        };
    }
    programEnded(part, program) {
        const inner = this.get(part.id);
        if (inner.program !== program)
            return;
        inner.program = null;
        if (inner.stopping)
            return;
        const during = inner.light === "starting" ? "while starting" : "unexpectedly";
        this.fail(inner, {
            title: part.help?.title ?? `${part.name} stopped ${during}`,
            text: part.help?.text ??
                "Look at the technical details, then press Try again.",
            details: program.log,
        });
    }
    async stopProgram(part) {
        const inner = this.get(part.id);
        if (!inner.program && !inner.starting) {
            // Nothing runs any more: a problem or a start cut short is cleared.
            if (inner.light === "problem" || inner.light === "starting")
                resetLight(inner);
            inner.stopping = false;
            return;
        }
        inner.stopping = true;
        await inner.program?.stop();
        inner.program = null;
        await inner.starting;
        resetLight(inner);
        inner.stopping = false;
    }
    // The watch: notices parts started or stopped outside the factory.
    async tick() {
        if (this.ticking)
            return;
        this.ticking = true;
        try {
            for (const part of this.parts)
                await this.watch(part);
        }
        finally {
            this.ticking = false;
        }
    }
    async watch(part) {
        const inner = this.get(part.id);
        if (inner.starting || inner.stopping || inner.program)
            return;
        if (inner.light === "none" || inner.light === "problem")
            return;
        const up = await this.answering(part);
        if (up === null)
            return;
        if (up && inner.light !== "running") {
            if (this.anotherCopyHas(part, inner))
                return;
            inner.outside = Boolean(part.run);
            this.set(inner, "running", null);
        }
        else if (!up && inner.light === "running") {
            resetLight(inner);
            this.notify();
        }
    }
    // A program of another copy of the project on the part's port is not this
    // part: it is said as a problem. True when it is so.
    anotherCopyHas(part, inner) {
        const port = portOf(part, this.parts, this.root);
        const other = port ? foreignFolder(port, folderOf(this.root, part)) : null;
        if (!port || !other)
            return false;
        failLight(inner, takenByAnotherCopy(part, port, other));
        this.notify();
        return true;
    }
    // Whether the part answers (its health address, else its port); null
    // when there is no way to tell.
    async answering(part) {
        const address = addressOf(part, this.parts, this.root);
        const port = portOf(part, this.parts, this.root);
        if (part.health && address && (await answers(address + part.health)))
            return true;
        // Its own program on its port, on an address the health check does
        // not try (a development server on IPv6 only).
        if (port && runsHere(port, folderOf(this.root, part)))
            return true;
        if (part.health && address)
            return false;
        return port ? await portTaken(port) : null;
    }
    dependentsOf(part) {
        const found = [];
        const visit = (id) => {
            for (const other of this.parts)
                if (other.dependsOn.includes(id) && !found.includes(other)) {
                    found.push(other);
                    visit(other.id);
                }
        };
        visit(part.id);
        return found.reverse();
    }
    set(inner, light, step) {
        setLight(inner, light, step);
        this.notify();
    }
    fail(inner, problem) {
        failLight(inner, problem);
        this.notify();
    }
    notify() {
        for (const listener of this.listeners)
            listener();
    }
    part(id) {
        return partById(this.parts, id);
    }
    get(id) {
        const inner = this.inner.get(id);
        if (!inner)
            throw new Error(`There is no part "${id}".`);
        return inner;
    }
}
